import { tags } from "typia";

/**
 * Summary representation of a shipment associated with one or more fulfillment
 * items.
 *
 * This DTO is used inside `IShoppingMallFulfillment` to provide lightweight
 * information about shipments without inlining the full shipment entity or all
 * tracking events. Clients can use the identifiers here to navigate to more
 * detailed shipment endpoints when necessary.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallShipmentSummary = {
  /**
   * Unique identifier of the shipment record.
   *
   * This corresponds to the primary key of a row in the
   * `shopping_mall_shipments` table.
   */
  id: string & tags.Format<"uuid">;

  /**
   * Carrier identifier or name for this shipment.
   *
   * When the shipment is handed off to a third-party logistics provider, this
   * field contains the carrier name or code that clients can display to end
   * users.
   */
  carrier?: string | undefined;

  /**
   * Tracking number associated with this shipment.
   *
   * The format depends on the carrier and is used by clients to present
   * tracking information in UI or link to carrier portals.
   */
  trackingNumber?: string | undefined;

  /**
   * Timestamp indicating when this shipment was dispatched.
   *
   * When present, this value helps users understand when the physical
   * hand-off to the carrier occurred.
   */
  shippedAt?: (string & tags.Format<"date-time">) | undefined;
};
